 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if out[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p = (y+dy, x+dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and out[p[0]][p[1]] == 5:
                        seen.add(p); stack.append(p)
            r0, r1 = min(y for y,x in cells), max(y for y,x in cells)
            c0, c1 = min(x for y,x in cells), max(x for y,x in cells)
            # Fill the hollow interior of the squared frame.
            for y in range(r0+1, r1):
                for x in range(c0+1, c1):
                    if out[y][x] == 0:
                        out[y][x] = 2
            # The break in the top edge emits a leftward beam one row above.
            top = {x for y,x in cells if y == r0}
            gaps = [x for x in range(c0, c1+1) if x not in top]
            if r0 > 0 and gaps:
                x = gaps[0]
                for k in range(x+1):
                    if out[r0-1][k] == 0:
                        out[r0-1][k] = 2
    return out

