 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    seen = set()
    frames = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == 5:
                        seen.add(p)
                        stack.append(p)
            r0, r1 = min(y for y, x in cells), max(y for y, x in cells)
            c0, c1 = min(x for y, x in cells), max(x for y, x in cells)
            top = {x for y, x in cells if y == r0}
            gaps = [x for x in range(c0, c1 + 1) if x not in top]
            gap = gaps[0] if gaps else None
            frames.append((r0, r1, c0, c1, gap))
            for y in range(r0 + 1, r1):
                for x in range(c0 + 1, c1):
                    if out[y][x] == 0:
                        out[y][x] = 2
            if gap is not None:
                # Extend the open segment in the top edge outward along its row.
                if r0 > 0:
                    nleft = sum(grid[r0][x] == 5 for x in range(c0, gap))
                    nright = sum(grid[r0][x] == 5 for x in range(gap + 1, c1 + 1))
                    ray = range(gap, -1, -1) if nleft >= nright else range(gap, w)
                    for x in ray:
                        if out[r0 - 1][x] == 0:
                            out[r0 - 1][x] = 2
                # The opening exposes and colors the interior.
                for y in range(r0 + 1, r1):
                    for x in range(c0 + 1, c1):
                        if out[y][x] == 0:
                            out[y][x] = 2
    # Vertically arranged frames produce a connecting beam in the gap, colored
